         * Uses thin-lens approximation logic for visual effect.
         */
        const canvas = document.getElementById('lensingCanvas');
        const ctx = canvas.getContext('2d');

        let width, height, centerX, centerY;
        let stars = [];
        let params = {
            mass: 72,
            alignment: 0
