        // Resize handling
        function resize() {
            const rect = canvas.parentElement.getBoundingClientRect();
            width = rect.width;
            height = rect.height;
            canvas.width = width;
            canvas.height = height;
            centerX = width / 2;
            centerY = height / 2;
            initStars();
        }

        window.addEventListener('resize', resize);

        // Initialize Star Field
        function initStars() {
            stars = [];
            // Create background stars (Source plane)
            for(let i=0; i<400; i++) {
                stars.push({
                    x: Math.random() * width,
                    y: Math.random() * height,
                    size: Math.random() * 1.5 + 0.5,
                    brightness: Math.random() * 0.5 + 0.5,
                    // Color variation (white/blueish)
                    r: Math.floor(200 + Math.random()*55),
                    g: Math.floor(200 + Math.random()*55),
                    b: 255
                });
            }
        }

        // The Core Rendering Loop
        function draw() {
            // Clear with dark gradient
            const grad = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, width);
            grad.addColorStop(0, '#0f1218');
            grad.addColorStop(1, '#05060a');
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, width, height);

            // Draw Dark Mass (Lens)
            ctx.beginPath();
            ctx.arc(centerX, centerY, 15, 0, Math.PI*2); // Small core
            ctx.fillStyle = '#000';
            ctx.fill();

            // Glow around lens
            const glowGrad = ctx.createRadialGradient(centerX, centerY, 10, centerX, centerY, 40);
            glowGrad.addColorStop(0, 'rgba(88, 166, 255, 0.2)');
            glowGrad.addColorStop(1, 'transparent');
            ctx.fillStyle = glowGrad;
            ctx.beginPath();
            ctx.arc(centerX, centerY, 40, 0, Math.PI*2);
            ctx.fill();

            // Draw Stars with Distortion
            const thetaE = params.mass; // Einstein Radius

            // Source position offset (for ring vs arcs)
            const sourceOffsetY = (params.alignment / 100) * 150;

            stars.forEach(star => {
                // Vector from lens center to star (Image Plane)
                let dx = star.x - centerX;
                let dy = star.y - centerY;
                let dist = Math.sqrt(dx*dx + dy*dy);

                if (dist === 0) return;

                // Simplified Thin Lens Equation visualization:
                // We distort the position where we draw the star based on distance to center.
                // Real physics: Deflection angle alpha = thetaE^2 / theta

                if (dist < thetaE * 4) { // Only compute distortion near lens

                    // Calculate deflection factor
                    // Stronger closer to center
                    let deflectionStrength = (thetaE * thetaE) / (dist + 1); 

                    // Normalize direction
                    let nx = dx / dist;
                    let ny = dy / dist;

                    // Apply radial stretch (creates the ring effect)
                    // If inside Einstein radius, push out. If outside, pull in slightly? 
                    // Visual trick: Radial smear or displacement.

                    let finalX = star.x;
                    let finalY = star.y;
                    let scaleSize = star.size;
                    let alpha = star.brightness;

                    // Tangential stretching for the ring look
                    // When close to thetaE, stretch tangentially
                    let diff = Math.abs(dist - thetaE);
                    if (diff < 30) {
                        // Stretch perpendicular to radial vector (tangential)
                        let tangentStretch = (1 - diff/30) * 15; 
                        // Rotate 90 deg
                        let tx = -ny * tangentStretch;
                        let ty = nx * tangentStretch;

                        finalX += tx;
                        finalY += ty;
                        scaleSize *= 2; // Brighter/Bigger on ring
                        alpha = 1;
                    } else if (dist < thetaE) {
                        // Inside radius: demagnify/push out visually
                        let pushFactor = 1 + ((thetaE - dist)/thetaE) * 0.5;
                        finalX = centerX + dx * pushFactor;
                        finalY = centerY + dy * pushFactor;
                        alpha *= 0.3; // Dim inside
                    } else {
                        // Outside: slight inward pull
                         let pullFactor = 1 - (thetaE/dist)*0.2;
                         finalX = centerX + dx * pullFactor;
                         finalY = centerY + dy * pullFactor;
                    }

                    // Draw the distorted star
                    ctx.globalAlpha = alpha;
                    ctx.fillStyle = `rgb(${star.r}, ${star.g}, ${star.b})`;
                    ctx.beginPath();
                    ctx.arc(finalX, finalY, scaleSize, 0, Math.PI*2);
                    ctx.fill();

                } else {
                    // Draw normal far away stars
                    ctx.globalAlpha = star.brightness * 0.5;
                    ctx.fillStyle = `rgb(${star.r}, ${star.g}, ${star.b})`;
                    ctx.beginPath();
                    ctx.arc(star.x, star.y, star.size, 0, Math.PI*2);
                    ctx.fill();
                }
            });

            // Draw explicit Ring Guide (subtle)
            ctx.beginPath();
            ctx.arc(centerX, centerY, thetaE, 0, Math.PI*2);
            ctx.strokeStyle = 'rgba(88, 166, 255, 0.1)';
            ctx.lineWidth = 1;
            ctx.stroke();

            requestAnimationFrame(draw);
        }

        // Event Listeners for Controls
